local DoughDividerMaker = {}
local PRODUCTS = {
    iron_doughdivider = { name = "Železni delilnik testa", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni delilnik testa za pekove." },
    bronze_doughdivider = { name = "Bronast delilnik testa", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast delilnik testa za pekove." },
    silver_doughdivider = { name = "Srebrn delilnik testa", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn delilnik testa za pekove." },
    gilded_doughdivider = { name = "Pozlačen delilnik testa", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen delilnik testa za pekove." },
    jewel_set_doughdivider = { name = "Draguljast delilnik testa", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast delilnik testa za pekove." },
    royal_sovereign_doughdivider = { name = "Kraljevski suveren delilnik testa", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren delilnik testa z biseri za krono." },
}
local BUILDINGS = {
    doughdivider_workshop = { name = "Doughdivider delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    doughdivider_house = { name = "Doughdivider hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_doughdivider_atelier = { name = "Mojstrski doughdivider atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_doughdivider_palace = { name = "Suverena doughdivider palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
DoughDividerMaker.ironStock=14; DoughDividerMaker.bronzeStock=12; DoughDividerMaker.woodStock=14; DoughDividerMaker.leatherStock=8; DoughDividerMaker.silverStock=8; DoughDividerMaker.goldStock=6; DoughDividerMaker.jewelStock=4; DoughDividerMaker.pearlStock=4
DoughDividerMaker.productStock = {}; DoughDividerMaker.buildings = {}; DoughDividerMaker.maker = nil; DoughDividerMaker.activeMaking = {}; DoughDividerMaker.totalProducts = 0; DoughDividerMaker.dayTimer = 0
function DoughDividerMaker.init() DoughDividerMaker.ironStock=14; DoughDividerMaker.bronzeStock=12; DoughDividerMaker.woodStock=14; DoughDividerMaker.leatherStock=8; DoughDividerMaker.silverStock=8; DoughDividerMaker.goldStock=6; DoughDividerMaker.jewelStock=4; DoughDividerMaker.pearlStock=4; DoughDividerMaker.productStock={}; DoughDividerMaker.buildings={}; DoughDividerMaker.maker=nil; DoughDividerMaker.activeMaking={}; DoughDividerMaker.totalProducts=0; DoughDividerMaker.dayTimer=0; print("[DoughDividerMaker] Royal Dough Divider Maker System initialized (6 products, 4 buildings)") end
function DoughDividerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DoughDividerMaker.maker={name=n or ("Delilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Delilnik najet: %s (spretnost: %d)",DoughDividerMaker.maker.name,s),"success") end; return true end
function DoughDividerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DoughDividerMaker.build(id) local ok,e=DoughDividerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DoughDividerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DoughDividerMaker.getQualityBonus() local b=0; for _,bd in ipairs(DoughDividerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DoughDividerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and DoughDividerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and DoughDividerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and DoughDividerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and DoughDividerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and DoughDividerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DoughDividerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DoughDividerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DoughDividerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DoughDividerMaker.buildings==0 then return false,"Potrebna delilna delavnica" end; if not DoughDividerMaker.maker then return false,"Potreben delilnik" end; return true end
function DoughDividerMaker.make(pt,qty) qty=qty or 1; local ok,e=DoughDividerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then DoughDividerMaker.ironStock=DoughDividerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then DoughDividerMaker.bronzeStock=DoughDividerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then DoughDividerMaker.woodStock=DoughDividerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then DoughDividerMaker.leatherStock=DoughDividerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then DoughDividerMaker.silverStock=DoughDividerMaker.silverStock-d.silverCost*qty end; if d.goldCost then DoughDividerMaker.goldStock=DoughDividerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DoughDividerMaker.jewelStock=DoughDividerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DoughDividerMaker.pearlStock=DoughDividerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DoughDividerMaker.maker then t=math.max(1,t-math.floor(DoughDividerMaker.maker.skill/13)) end; table.insert(DoughDividerMaker.activeMaking,{id="doughdivider_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DoughDividerMaker.completeMaking(m) local q=1.0+(DoughDividerMaker.getQualityBonus()/100); if DoughDividerMaker.maker then q=q+(DoughDividerMaker.maker.skill/140) end; q=math.min(2.5,q); DoughDividerMaker.productStock[m.productType]=(DoughDividerMaker.productStock[m.productType] or 0)+m.quantity; DoughDividerMaker.totalProducts=DoughDividerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DoughDividerMaker.maker then DoughDividerMaker.maker.itemsMade=DoughDividerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DoughDividerMaker.maker.skill=math.min(100,DoughDividerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Delilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"doughdivider.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function DoughDividerMaker.update(dt) if not _G.state then return end; DoughDividerMaker.dayTimer=DoughDividerMaker.dayTimer+dt; if DoughDividerMaker.dayTimer>=30 then DoughDividerMaker.dayTimer=0; for i=#DoughDividerMaker.activeMaking,1,-1 do local m=DoughDividerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DoughDividerMaker.completeMaking(m); table.remove(DoughDividerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DoughDividerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DoughDividerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DoughDividerMaker.getStats() return {ironStock=DoughDividerMaker.ironStock,bronzeStock=DoughDividerMaker.bronzeStock,woodStock=DoughDividerMaker.woodStock,leatherStock=DoughDividerMaker.leatherStock,silverStock=DoughDividerMaker.silverStock,goldStock=DoughDividerMaker.goldStock,jewelStock=DoughDividerMaker.jewelStock,pearlStock=DoughDividerMaker.pearlStock,productStock=DoughDividerMaker.productStock,numBuildings=#DoughDividerMaker.buildings,hasMaker=DoughDividerMaker.maker~=nil,makerName=DoughDividerMaker.maker and DoughDividerMaker.maker.name or "—",makerSkill=DoughDividerMaker.maker and DoughDividerMaker.maker.skill or 0,activeMaking=#DoughDividerMaker.activeMaking,totalProducts=DoughDividerMaker.totalProducts} end
return DoughDividerMaker
